<script setup>
import { ref, computed, nextTick, onMounted, onBeforeUnmount } from 'vue'
import { Code2, Users, Plus, ArrowRight, ArrowLeft, Play, Copy, Check, LogOut, Link2, Terminal, History, X, Clock, ShieldCheck } from 'lucide-vue-next'
import { monaco } from './editor'
import AiProblemPicker from './AiProblemPicker.vue'
import AiPanel from './AiPanel.vue'
import { descriptionFor, templateFor } from './problemTemplates'

const me=ref(null), mode=ref('login'), auth=ref({email:'',password:'',displayName:''})
const rooms=ref([]), room=ref(null), page=ref('home'), error=ref(''), toast=ref(''), busy=ref(false)
const form=ref({title:'',prompt:'',problemId:null,durationMinutes:45}), invitation=ref(''), joinUrl=ref('')
const language=ref('python'), version=ref(0), presence=ref(0), connection=ref('offline')
const cases=ref([{input:'',expected:''}]), submissions=ref([]), feedback=ref(null), feedbackForm=ref({score:4,notes:''})
const revisions=ref([]), replayIndex=ref(null), conflict=ref(null), host=ref(null)
let editor=null, socket=null, poll=null, reconnect=null, editTimer=null, pending=false, dirty=false, applying=false, cursorDecorations=[]
const role=computed(()=>room.value?.interviewerId===me.value?.id?'Interviewer':'Candidate')
const editable=computed(()=>room.value?.status==='LIVE'||(room.value?.status==='OPEN'&&role.value==='Interviewer'))
const latest=computed(()=>submissions.value[0])
async function api(path,opts={}) {
  const response=await fetch('/api'+path,{credentials:'same-origin',headers:{'Content-Type':'application/json'},...opts})
  if(!response.ok){let data={};try{data=await response.json()}catch{}throw new Error(data.error||'Request failed ('+response.status+')')}
  const text=await response.text();return text?JSON.parse(text):null
}
function notify(message){toast.value=message;setTimeout(()=>{if(toast.value===message)toast.value=''},4500)}
function clearInviteUrl(){const url=new URL(location.href);if(!url.searchParams.has('room')&&!url.searchParams.has('invite'))return;url.searchParams.delete('room');url.searchParams.delete('invite');history.replaceState(null,'',url.pathname+url.search+url.hash)}
async function dashboard(){rooms.value=await api('/rooms')}
async function authenticate(){busy.value=true;error.value='';try{me.value=await api('/auth/'+mode.value,{method:'POST',body:JSON.stringify(auth.value)});auth.value.password='';await dashboard();await maybeJoin()}catch(e){error.value=e.message}finally{busy.value=false}}
async function logout(){try{await api('/auth/logout',{method:'POST'})}finally{closeRoom();me.value=null;rooms.value=[];page.value='home';error.value=''}}
async function create(){busy.value=true;error.value='';try{const created=await api('/rooms',{method:'POST',body:JSON.stringify(form.value)});await dashboard();await openRoom(created.room.id);invitation.value=location.origin+'/?room='+created.room.id+'&invite='+created.inviteToken;notify('Room created. Share the invitation link.')}catch(e){error.value=e.message}finally{busy.value=false}}
function applyProblem(problem){const sample=problem.sampleCases?.[0];form.value.title=problem.title;form.value.prompt=problem.prompt+(sample?'\n\nSample stdin:\n'+sample.input+'Sample stdout:\n'+sample.expected:'');form.value.problemId=problem.id}
async function join(){error.value='';try{const url=new URL(joinUrl.value),id=url.searchParams.get('room'),token=url.searchParams.get('invite');if(!id||!token)throw new Error('Paste a valid invitation link');await api('/rooms/'+id+'/join',{method:'POST',body:JSON.stringify({inviteToken:token})});clearInviteUrl();joinUrl.value='';await dashboard();await openRoom(id);notify('You joined the room')}catch(e){page.value='join';error.value=e.message}}
async function maybeJoin(){if(new URL(location.href).searchParams.has('invite')){joinUrl.value=location.href;await join()}}
function closeRoom(){if(socket){socket.onclose=null;socket.close();socket=null}clearInterval(poll);clearTimeout(reconnect);clearTimeout(editTimer);if(editor){editor.dispose();editor=null}room.value=null;invitation.value='';connection.value='offline';conflict.value=null;pending=false;dirty=false;replayIndex.value=null}
async function back(){closeRoom();clearInviteUrl();page.value='home';error.value='';if(me.value)await dashboard()}
async function openRoom(id){closeRoom();error.value='';room.value=await api('/rooms/'+id);clearInviteUrl();page.value='room';version.value=room.value.version;language.value=room.value.language;await nextTick();mountEditor(room.value.code);if(room.value.problemId&&!(room.value.code||'').trim()&&editable.value)loadTemplate();connect(id);await sideData();poll=setInterval(async()=>{try{const fresh=await api('/rooms/'+id);if(room.value?.id===id){room.value={...room.value,status:fresh.status,candidateId:fresh.candidateId,candidateName:fresh.candidateName,startedAt:fresh.startedAt,endedAt:fresh.endedAt};editor?.updateOptions({readOnly:!editable.value});await loadSubmissions()}}catch{}},4000)}
function mountEditor(code){editor=monaco.editor.create(host.value,{value:code,language:language.value,theme:'interviewlab',automaticLayout:true,fontFamily:'Cascadia Code, Consolas, monospace',fontSize:14,lineHeight:23,minimap:{enabled:false},scrollBeyondLastLine:false,padding:{top:20,bottom:20},readOnly:!editable.value});editor.onDidChangeModelContent(()=>{if(applying||replayIndex.value!==null)return;dirty=true;scheduleEdit()});editor.onDidChangeCursorPosition(e=>{if(socket?.readyState===1)socket.send(JSON.stringify({type:'cursor',line:e.position.lineNumber,column:e.position.column}))})}
function setCode(code){if(!editor||editor.getValue()===code)return;applying=true;editor.setValue(code);applying=false}
function connect(id){if(room.value?.id!==id)return;connection.value='connecting';socket=new WebSocket((location.protocol==='https:'?'wss:':'ws:')+'//'+location.host+'/ws/rooms/'+id);socket.onopen=()=>{connection.value='connected';if(dirty)scheduleEdit()};socket.onclose=e=>{console.warn('InterviewLab socket closed',e.code,e.reason);if(pending){dirty=true;pending=false}connection.value='reconnecting';if(room.value?.id===id)reconnect=setTimeout(()=>connect(id),1600)};socket.onmessage=e=>{const msg=JSON.parse(e.data);if(msg.type==='snapshot'||msg.type==='code'){const r=msg.room;const sameVersion=r.version===version.value;version.value=r.version;room.value={...room.value,...r};language.value=r.language;if(msg.type==='code'&&msg.authorId===me.value.id){pending=false;if(!dirty)setCode(r.code);else scheduleEdit()}else if(msg.type==='snapshot'&&dirty&&sameVersion){pending=false;scheduleEdit()}else if(dirty&&editor?.getValue()!==r.code){conflict.value={local:editor.getValue(),server:r.code};pending=false}else{setCode(r.code);dirty=false;pending=false}monaco.editor.setModelLanguage(editor.getModel(),language.value)}else if(msg.type==='conflict'){pending=false;conflict.value={local:editor.getValue(),server:msg.room.code};version.value=msg.room.version;room.value={...room.value,...msg.room}}else if(msg.type==='presence')presence.value=msg.count;else if(msg.type==='submission')loadSubmissions();else if(msg.type==='cursor'&&editor)cursorDecorations=editor.deltaDecorations(cursorDecorations,[{range:new monaco.Range(msg.line,msg.column,msg.line,msg.column+1),options:{className:'remote-cursor',hoverMessage:{value:'Other participant'}}}])}}
function scheduleEdit(){clearTimeout(editTimer);editTimer=setTimeout(flushEdit,450)}
function flushEdit(){if(!dirty||pending||conflict.value||socket?.readyState!==1||!editable.value)return;pending=true;dirty=false;socket.send(JSON.stringify({type:'edit',code:editor.getValue(),language:language.value,baseVersion:version.value}))}
function resolveConflict(local){const draft=conflict.value.local,shared=conflict.value.server;conflict.value=null;pending=false;setCode(local?draft:shared);dirty=local;if(local)scheduleEdit();else notify('Loaded the shared version')}
function loadTemplate(){
  const starter=templateFor(room.value?.problemId,language.value)
  if(!starter||!editor||!editable.value||replayIndex.value!==null)return
  const current=editor.getValue()
  if(current===starter)return
  if(current.trim()&&!window.confirm('Replace the current code with the starter template?'))return
  setCode(starter)
  dirty=true
  scheduleEdit()
  notify('Starter template loaded')
}
function changeLanguage(){
  const previous=room.value?.language
  const current=editor?.getValue()||''
  const oldStarter=templateFor(room.value?.problemId,previous)
  const nextStarter=templateFor(room.value?.problemId,language.value)
  monaco.editor.setModelLanguage(editor.getModel(),language.value)
  if(nextStarter&&(!current.trim()||current===oldStarter))setCode(nextStarter)
  dirty=true
  scheduleEdit()
}
async function transition(action){try{room.value=await api('/rooms/'+room.value.id+'/'+action,{method:'POST'});editor?.updateOptions({readOnly:!editable.value});notify(action==='start'?'Interview is live':'Interview completed')}catch(e){error.value=e.message}}
async function sideData(){await Promise.all([loadSubmissions(),loadFeedback()])}
async function loadSubmissions(){if(room.value)submissions.value=await api('/rooms/'+room.value.id+'/submissions')}
async function loadFeedback(){if(room.value)feedback.value=await api('/rooms/'+room.value.id+'/feedback')}
async function run(){try{error.value='';const custom=cases.value.filter(item=>item.input||item.expected);const submission=await api('/rooms/'+room.value.id+'/submissions',{method:'POST',headers:{'Content-Type':'application/json','Idempotency-Key':crypto.randomUUID()},body:JSON.stringify({cases:custom})});submissions.value=[submission,...submissions.value];notify('Submission queued')}catch(e){error.value=e.message}}
async function saveFeedback(){try{feedback.value=await api('/rooms/'+room.value.id+'/feedback',{method:'PUT',body:JSON.stringify(feedbackForm.value)});notify('Feedback saved')}catch(e){error.value=e.message}}
async function showReplay(){revisions.value=await api('/rooms/'+room.value.id+'/revisions');if(!revisions.value.length){notify('No code history yet');return}replayIndex.value=revisions.value.length-1;setCode(revisions.value[replayIndex.value].code);editor?.updateOptions({readOnly:true})}
function replayAt(index){replayIndex.value=Number(index);setCode(revisions.value[replayIndex.value].code)}
function endReplay(){replayIndex.value=null;setCode(room.value.code);editor?.updateOptions({readOnly:!editable.value})}
async function copyInvite(){await navigator.clipboard.writeText(invitation.value);notify('Invitation copied')}
async function refreshInvite(){try{const response=await api('/rooms/'+room.value.id+'/invitation',{method:'POST'});invitation.value=location.origin+'/?room='+room.value.id+'&invite='+response.inviteToken;await copyInvite()}catch(e){error.value=e.message}}
function result(s){try{return JSON.parse(s?.resultJson||'{}')}catch{return {}}}
function date(s){return s?new Date(s).toLocaleString('en-US', {month:'short',day:'numeric',hour:'numeric',minute:'2-digit'}):''}
onMounted(async()=>{try{me.value=await api('/auth/me');await dashboard();await maybeJoin()}catch{me.value=null}})
onBeforeUnmount(closeRoom)
</script>

<template>
<div class="shell">
  <aside class="sidebar">
    <div class="brand"><span class="brand-icon"><Code2 :size="20"/></span>interview<span>lab</span></div>
    <div class="side-label">WORKSPACE</div>
    <button class="nav-item" :class="{selected:page==='home'}" @click="back"><Users :size="17"/> My interviews</button>
    <button class="nav-item" :class="{selected:page==='create'}" @click="closeRoom();page='create';error=''"><Plus :size="17"/> Create room</button>
    <button class="nav-item" :class="{selected:page==='join'}" @click="closeRoom();page='join';error=''"><Link2 :size="17"/> Join with link</button>
    <div class="side-bottom"><div class="side-callout"><ShieldCheck :size="20"/><p>Practice with purpose.<br/><span>Build confidence together.</span></p></div><div v-if="me" class="profile"><span class="avatar">{{ me.displayName?.slice(0,1).toUpperCase() }}</span><span><strong>{{ me.displayName }}</strong><small>{{ me.email }}</small></span><button title="Log out" @click="logout"><LogOut :size="17"/></button></div></div>
  </aside>
  <main class="main">
    <header class="topbar"><div>Workspace <span>/</span> <strong>{{ page==='room'?room?.title:page==='create'?'New interview':page==='join'?'Join interview':'Overview' }}</strong></div><div class="top-status"><span class="dot"></span> Practice space</div></header>
    <div v-if="toast" class="toast"><Check :size="16"/> {{ toast }}</div>
    <div v-if="error" class="error">{{ error }} <button @click="error=''">×</button></div>
    <div v-if="!me" class="auth-layout">
      <section class="auth-hero"><div class="eyebrow">YOUR NEXT INTERVIEW STARTS HERE</div><h1>Practice the way<br/><em>interviews happen.</em></h1><p>Live code collaboration, real execution, and thoughtful feedback in one focused space.</p><div class="hero-points"><span><Users :size="18"/> Collaborate live</span><span><Terminal :size="18"/> Run real code</span><span><Check :size="18"/> Grow with feedback</span></div><div class="code-preview"><div class="preview-head"><span>● ● ●</span> interview.py <b>● Live session</b></div><pre>def two_sum(nums, target):<br/>    seen = {}<br/>    for i, num in enumerate(nums):<br/>        complement = target - num<br/>        if complement in seen:<br/>            return [seen[complement], i]<br/>        seen[num] = i</pre><div class="preview-foot">● All tests passed <span>2 collaborators online</span></div></div></section>
      <section class="auth-card"><div class="eyebrow dark">INTERVIEWLAB</div><h2>{{ mode==='login'?'Welcome back':'Create your account' }}</h2><p>{{ mode==='login'?'Log in to pick up where you left off.':'Make a space to practice with your peers.' }}</p><form @submit.prevent="authenticate"><label v-if="mode==='register'">Your name<input v-model="auth.displayName" required maxlength="80" placeholder="Alex Morgan"/></label><label>Email address<input v-model="auth.email" required type="email" placeholder="you@example.com"/></label><label>Password<input v-model="auth.password" required type="password" minlength="8" placeholder="At least 8 characters"/></label><button class="primary full" :disabled="busy">{{ busy?'Please wait...':mode==='login'?'Log in':'Create account' }} <ArrowRight :size="17"/></button></form><div class="auth-switch">{{ mode==='login'?'New to InterviewLab?':'Already have an account?' }} <button @click="mode=mode==='login'?'register':'login';error=''">{{ mode==='login'?'Create an account':'Log in' }}</button></div></section>
    </div>
    <div v-else-if="page==='home'" class="content"><div class="heading"><div><div class="eyebrow dark">YOUR PRACTICE SPACE</div><h1>Make the next one <em>count.</em></h1><p>Create a room, invite a partner, and turn practice into progress.</p></div><button class="primary" @click="page='create'"><Plus :size="18"/> New interview</button></div><div class="stats"><div><span class="stat-icon mint"><Users :size="20"/></span><small>Total interviews</small><strong>{{ rooms.length }}</strong><p>Every session is a step forward</p></div><div><span class="stat-icon purple"><Code2 :size="20"/></span><small>In progress</small><strong>{{ rooms.filter(r=>r.status==='LIVE').length }}</strong><p>Live practice sessions</p></div><div><span class="stat-icon peach"><Check :size="20"/></span><small>Completed</small><strong>{{ rooms.filter(r=>r.status==='ENDED').length }}</strong><p>Lessons to carry forward</p></div></div><div class="section-title"><div><h2>Your interviews</h2><p>Pick up a session or start something new.</p></div><button @click="page='join'">Have an invite? <ArrowRight :size="16"/></button></div><div v-if="!rooms.length" class="empty"><span><Code2 :size="30"/></span><h3>Your practice starts here</h3><p>Create your first room and invite someone to interview with you.</p><button class="primary" @click="page='create'"><Plus :size="17"/> Create a room</button></div><div v-else class="room-list"><button v-for="item in rooms" :key="item.id" @click="openRoom(item.id)"><span class="room-icon"><Code2 :size="19"/></span><span class="room-desc"><strong>{{ item.title }}</strong><small>{{ item.interviewerId===me.id?'You are interviewing':'You are the candidate' }} · {{ date(item.createdAt) }}</small></span><span class="badge" :class="item.status.toLowerCase()">{{ item.status==='OPEN'?'Waiting':item.status==='LIVE'?'Live':'Completed' }}</span><ArrowRight :size="17"/></button></div></div>
    <div v-else-if="page==='create'" class="content narrow"><button class="back" @click="back"><ArrowLeft :size="16"/> Back to interviews</button><div class="form-heading"><div class="eyebrow dark">SET THE STAGE</div><h1>Create an interview room.</h1><p>A focused space for you and one candidate to solve a problem together.</p></div><AiProblemPicker @selected="applyProblem"/><form class="panel form-panel" @submit.prevent="create"><label>Interview title<small>Give this session a name</small><input v-model="form.title" required maxlength="150" placeholder="e.g. Arrays & Hash Maps — Mock Interview"/></label><label>Problem statement<small>Describe the challenge for your candidate</small><textarea v-model="form.prompt" @input="form.problemId=null" required maxlength="10000" rows="9" placeholder="Given an array of integers nums and an integer target..."></textarea></label><small v-if="form.problemId">Curated tests attached: {{ form.problemId }}. Editing the statement switches to a custom problem.</small><label>Session length<small>A little structure helps the practice feel real</small><select v-model.number="form.durationMinutes"><option :value="30">30 minutes</option><option :value="45">45 minutes</option><option :value="60">60 minutes</option><option :value="90">90 minutes</option></select></label><div class="form-actions"><button type="button" class="secondary" @click="back">Cancel</button><button class="primary" :disabled="busy">Create room <ArrowRight :size="17"/></button></div></form></div>
    <div v-else-if="page==='join'" class="content narrow"><button class="back" @click="back"><ArrowLeft :size="16"/> Back to interviews</button><div class="form-heading"><div class="eyebrow dark">JOIN THE SESSION</div><h1>Have an invitation?</h1><p>Paste the link your interviewer shared to enter the coding room.</p><p v-if="me" class="hint">Signed in as {{ me.displayName }} ({{ me.email }}). If another account already joined, log out and sign in with that account.</p></div><form class="panel form-panel" @submit.prevent="join"><label>Invitation link<input v-model="joinUrl" required type="url" placeholder="https://example.com/?room=...&invite=..."/></label><div class="form-actions"><button class="primary">Join room <ArrowRight :size="17"/></button></div></form></div>
    <div v-else-if="page==='room'&&room" class="room-page"><div class="room-heading"><div><button class="back" @click="back"><ArrowLeft :size="15"/> All interviews</button><div class="title-line"><h1>{{ room.title }}</h1><span class="badge" :class="room.status.toLowerCase()">{{ room.status==='OPEN'?'Waiting':room.status==='LIVE'?'Live session':'Completed' }}</span></div><p>{{ role }} · {{ room.durationMinutes }} min · {{ room.candidateName ? room.interviewerName+' & '+room.candidateName : 'Waiting for candidate' }}</p></div><div class="room-actions"><span class="connection"><span class="dot"></span>{{ connection }} · {{ presence }} online</span><button v-if="role==='Interviewer'&&room.status==='OPEN'&&room.candidateId" class="primary compact" @click="transition('start')"><Play :size="15"/> Start interview</button><button v-if="role==='Interviewer'&&room.status==='LIVE'" class="secondary compact" @click="transition('end')">End interview</button></div></div>
      <div v-if="role==='Interviewer'&&room.status==='OPEN'&&!room.candidateId" class="invite"><div><Link2 :size="19"/><span><strong>Invite your candidate</strong><small>Share this private link to bring them into the room.</small></span></div><button class="secondary compact" @click="invitation?copyInvite():refreshInvite()"><Copy :size="15"/> {{ invitation?'Copy invitation':'Generate invitation' }}</button></div>
      <div class="workspace"><section class="panel problem"><div class="panel-top"><Code2 :size="16"/> Problem</div><div class="problem-inner"><div class="meta">INTERVIEW PROMPT <span><Clock :size="14"/> {{ room.durationMinutes }} MIN</span></div><h2>{{ room.title }}</h2><p v-if="descriptionFor(room.problemId)" class="problem-description">{{ descriptionFor(room.problemId) }}</p><p>{{ room.prompt }}</p><div class="tip"><ShieldCheck :size="18"/> Think aloud as you work. Explain your approach and test edge cases.</div></div></section><section class="panel code"><div class="code-top"><span><Code2 :size="15"/> {{ language==='python'?'solution.py':'Main.java' }}</span><div class="code-controls"><button v-if="templateFor(room.problemId,language)" class="starter-button" :disabled="!editable||replayIndex!==null" @click="loadTemplate">Load template</button><select v-model="language" :disabled="!editable||replayIndex!==null" @change="changeLanguage"><option value="python">Python 3</option><option value="java">Java 17</option></select></div></div><div ref="host" class="editor"></div><div class="code-foot"><span>● {{ connection==='connected'?'Synced':'Reconnecting' }} · v{{ version }}</span><span>{{ editable?'Changes save automatically':'Read only' }}</span></div></section><section class="panel tools"><div class="panel-top"><Terminal :size="17"/> Test & run</div><div class="tools-inner"><div class="tool-title">Custom test cases <span>{{ cases.length }}/5</span></div><div v-for="(item,index) in cases" :key="index" class="test-case"><div>CASE {{ index+1 }} <button v-if="cases.length>1" @click="cases.splice(index,1)">Remove</button></div><label>Input<textarea v-model="item.input" rows="2" placeholder="stdin input"></textarea></label><label>Expected output<textarea v-model="item.expected" rows="2" placeholder="expected stdout"></textarea></label></div><button v-if="cases.length<5" class="add-case" @click="cases.push({input:'',expected:''})"><Plus :size="15"/> Add test case</button><button class="run" :disabled="room.status!=='LIVE'" @click="run"><Play :size="15" fill="currentColor"/> Run code</button><small v-if="room.status!=='LIVE'" class="hint">Start the interview to run code.</small><div class="result"><div class="tool-title">Latest result <span v-if="latest" class="badge" :class="latest.status.toLowerCase()">{{ latest.status }}</span></div><div v-if="!latest" class="result-empty"><Terminal :size="22"/><p>Test results will appear here.</p></div><template v-else><p v-if="result(latest).error" class="result-error">{{ result(latest).error }}</p><div v-for="item in result(latest).cases||[]" :key="item.case" class="case-result"><strong :class="item.passed?'pass':'fail'">{{ item.passed?'✓':'×' }} Case {{ item.case }} {{ item.passed?'passed':'failed' }}</strong><pre v-if="!item.passed&&!item.hidden">Expected: {{ item.expected }}&#10;Actual: {{ item.actual }}</pre><small v-if="item.hidden&&!item.passed" class="hint">Hidden case failed; input and expected output are withheld.</small></div><small v-if="['QUEUED','RUNNING'].includes(latest.status)" class="hint">{{ latest.status==='QUEUED'?'Waiting for a worker...':'Running in a container...' }}</small></template></div><button class="history-link" @click="showReplay"><History :size="16"/> View code history <ArrowRight :size="14"/></button></div></section></div>
      <AiPanel :room="room" :me="me"/>
      <section v-if="room.status==='ENDED'" class="panel feedback"><div><div class="eyebrow dark">POST INTERVIEW</div><h2>Feedback & reflection</h2><p>Capture what went well and what to improve.</p></div><div v-if="feedback" class="saved-feedback"><strong>{{ feedback.score }}<small>/5</small></strong><p>{{ feedback.notes }}</p></div><form v-else-if="role==='Interviewer'" @submit.prevent="saveFeedback"><label>Score<select v-model.number="feedbackForm.score"><option v-for="n in 5" :key="n" :value="n">{{ n }} / 5</option></select></label><label>Notes<textarea v-model="feedbackForm.notes" required maxlength="5000" rows="3" placeholder="Strengths, improvement areas, next steps..."></textarea></label><button class="primary compact">Save feedback <ArrowRight :size="15"/></button></form><p v-else class="hint">Your interviewer has not shared feedback yet.</p></section>
      <div v-if="conflict" class="modal-layer"><div class="modal"><h2>Code changed while you were editing</h2><p>Another participant saved a newer version. Your draft is preserved. Choose which version to keep.</p><div><button class="secondary" @click="resolveConflict(false)">Use shared version</button><button class="primary" @click="resolveConflict(true)">Keep my draft</button></div></div></div>
      <div v-if="replayIndex!==null" class="replay"><History :size="17"/><strong>Code history</strong><span>Version {{ revisions[replayIndex]?.version }} of {{ revisions.length }}</span><input type="range" :min="0" :max="revisions.length-1" :value="replayIndex" @input="replayAt($event.target.value)"/><span>{{ date(revisions[replayIndex]?.createdAt) }}</span><button @click="endReplay"><X :size="18"/></button></div>
    </div>
  </main>
</div>
</template>
